//! Exclusive selected CHECK uses the actual existing Handler preparation/producer.
#[path="../../../shared/test_scratch.rs"]mod scratch;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod report_configuration;
use dmbc::{policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q},request::{BuildRequest,BuildOutcome,Command},runner_host::{BuildHost,FullRegistryCheckOptions}};
use std::path::{Path,PathBuf};
fn put(root:&Path,relative:&str,text:impl AsRef<[u8]>){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,text).unwrap();}
fn fixture(label:&str,full:bool)->PathBuf{let root=std::fs::canonicalize(scratch::dir(label)).unwrap();put(&root,"tools/ci/lint_scopes.toml",report_configuration::with_overlay(""));
 put(&root,"code/__defines/context.dm","#define CAPABILITIES(...)\n#define PROC_REF(P) #P\n/datum/act\n/datum/act/eval\n/obj/probe\n");
 put(&root,"code/structural.dm","/proc/leak(datum/act/A)\n    return list(A)\n/proc/allowed(datum/act/A)\n    return list(A) // ALLOW(handlers): preserve actual raw annotation consumption in native report\n");
 let mut manifest="#include \"code/__defines/context.dm\"\n#include \"code/structural.dm\"\n".to_owned();
 if full{put(&root,"code/handler.dm","/obj/probe/proc/handler(datum/act/eval/A)\n    return 2\nCAPABILITIES(/obj/probe,when(PROC_REF(handler)))\n");put(&root,"code/engine/present/protocols.dm","/datum/look\n/atom/proc/draw(datum/look/look)\n    return\n");put(&root,"code/output.dm","/obj/bad/draw(extra,datum/look/look)\n    return\n");manifest.push_str("#include \"code/handler.dm\"\n#include \"code/engine/present/protocols.dm\"\n#include \"code/output.dm\"\n");}
 put(&root,"deepquarry.dme",manifest);root}
fn request(root:&Path)->BuildRequest{let Command::Build(request)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("actual public preparation")};let mut request=*request;request.no_cache=true;request.exact_inputs=true;request.progress_enabled=false;request.workers=1;request.timeout_seconds=Some(60);request.engine_template=None;request.bootstrap_catalog=false;request.cache_root=Some(scratch::dir("selected-handler-check-cache"));request.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.to_owned(),recursive_roots:["code","doc/rewrite","interface","maps","modular_chomp","tgui"].map(|part|root.join(part)).to_vec(),configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_auxiliary:Vec::new(),..Default::default()});request}

fn no_products(root:&Path){for item in std::fs::read_dir(root).unwrap(){let item=item.unwrap();let path=item.path();if item.file_type().unwrap().is_dir(){no_products(&path)}else{assert!(!matches!(path.extension().and_then(|v|v.to_str()),Some("dmb"|"rsc")),"{}",path.display());}}}
#[test]fn actual_selected_handler_partial_check_skips_unrequested_physical_root_and_baselines(){
 let root=fixture("selected-handler-partial",false);std::fs::remove_file(root.join("deepquarry.dme")).unwrap();std::fs::create_dir(root.join("deepquarry.dme")).unwrap();
 let mut host=BuildHost::default();for ci in [false,true]{let(mut diagnostics,mut text)=(Vec::new(),Vec::new());
  let clean=host.write_selected_registry_check(request(&root),FullRegistryCheckOptions{ci,..Default::default()},&["sem/handlers".into()],&mut diagnostics,&mut text).unwrap();
  let text=String::from_utf8(text).unwrap();assert!(!clean,"real context escape remains Hard failure");assert!(text.contains("code/structural.dm"));assert!(!text.contains("allow annotations:")&&!text.contains("base_vars"));assert_eq!(text.contains("::group::sem/handlers"),ci);assert!(root.join("deepquarry.dme").is_dir());
 }
 assert!(host.symbolic_retention_stats().is_none_or(|stats|stats.records==0&&stats.successful_admissions==0));no_products(&root);
}
