#[test]fn actual_handler_unused_union_same_stamp_maps_change_refuses_then_reprepares(){
 use std::io::Write;struct Restore{path:PathBuf,bytes:Vec<u8>,modified:std::time::SystemTime}impl Drop for Restore{fn drop(&mut self){std::fs::write(&self.path,&self.bytes).unwrap();std::fs::OpenOptions::new().write(true).open(&self.path).unwrap().set_times(std::fs::FileTimes::new().set_modified(self.modified)).unwrap();}}
 struct Change<'a>{restore:&'a Restore,changed:bool,bytes:Vec<u8>}impl Write for Change<'_>{fn write(&mut self,bytes:&[u8])->std::io::Result<usize>{self.bytes.extend_from_slice(bytes);if !self.changed{let mut altered=self.restore.bytes.clone();let at=altered.iter().position(|byte|*byte==b'A').unwrap();altered[at]=b'B';std::fs::write(&self.restore.path,altered)?;std::fs::OpenOptions::new().write(true).open(&self.restore.path)?.set_times(std::fs::FileTimes::new().set_modified(self.restore.modified))?;self.changed=true;}Ok(bytes.len())}fn flush(&mut self)->std::io::Result<()>{Ok(())}}
 let root=fixture("source-handler-maps-stale",false);put(&root,"maps/observed.dm","// SOURCE_HANDLER_MAP_A\n");let path=root.join("maps/observed.dm");let restore=Restore{bytes:std::fs::read(&path).unwrap(),modified:std::fs::metadata(&path).unwrap().modified().unwrap(),path};let selectors=handler_only_full_selectors();let mut host=BuildHost::default();let(mut diagnostics,mut output)=(Vec::new(),Change{restore:&restore,changed:false,bytes:Vec::new()});let error=host.write_selected_registry_check(request(&root),FullRegistryCheckOptions::default(),&selectors,&mut diagnostics,&mut output).unwrap_err();assert!(output.changed&&!output.bytes.is_empty());assert!(error.to_string().contains("changed")||error.to_string().contains("stale"),"{error}");drop(output);drop(restore);let mut report=Vec::new();assert!(!host.write_selected_registry_check(request(&root),FullRegistryCheckOptions::default(),&selectors,&mut diagnostics,&mut report).unwrap());assert!(!report.is_empty());no_products(&root);
}


#[path="../../../shared/test_native_transport.rs"]mod source_handler_transport;
#[test]
#[ignore="private native IPC; run exact outside Cargo under dm_compile machine slot"]
fn actual_resident_source_handler_union_seals_distinct_actual_frames_and_requested_options(){
 use std::{ffi::OsString,time::Duration};use dq_analyze::{full_registry_check_wire::{CheckFrame,Scope,Terminal},full_registry_check_selection_wire::SelectionBinding};
 let selectors=vec!["scheduler".to_owned(),"sem/handlers".to_owned()];let expected=SelectionBinding::for_selectors(&selectors).unwrap();
 for full in[false,true]{let root=source_handler_fixture(if full{"resident-source-handler-full"}else{"resident-source-handler-structural"},full);if full{let path=root.join("deepquarry.dme");let mut text=std::fs::read_to_string(&path).unwrap();text.push_str("#warn SOURCE_HANDLER_UNION_NOTICE\n");std::fs::write(path,text).unwrap();}
  let transport_root=scratch::dir("resident-source-handler-transport");let transport=source_handler_transport::LibraryTransport{root:&transport_root,namespace:format!("source-handler-{}-{full}",std::process::id())};
  let mut arguments=vec![OsString::from("analyze-full-check"),OsString::from("--workspace"),root.as_os_str().to_owned(),OsString::from("--no-selftest")];for name in &selectors{arguments.push("--lint".into());arguments.push(name.into())}let arguments=arguments.iter().map(OsString::as_os_str).collect::<Vec<_>>();let actual=transport.run_program_with_trace(Path::new(env!("CARGO_BIN_EXE_dmbc")),&arguments,Duration::from_secs(90),true).unwrap();assert!(matches!(actual.status.code(),Some(0|1)),"{}",String::from_utf8_lossy(&actual.stderr));assert!(actual.stderr.is_empty(),"operational traces must stay in the lifecycle log: {}",String::from_utf8_lossy(&actual.stderr));
  let end=actual.stdout.iter().take(dq_analyze::selected_exclusions_wire::MAX_HEADER).position(|byte|*byte==b'\n').unwrap();let terminal:Terminal=serde_json::from_slice(&actual.stdout[..end]).unwrap();terminal.require(FullRegistryCheckOptions::default(),expected).unwrap();assert_eq!(terminal.scope,Scope::RegistrySelection);assert_eq!(terminal.selected,2);assert!(terminal.registered>2&&terminal.options.unused);assert_eq!(terminal.clean,actual.status.code()==Some(0));
  let CheckFrame::SourceHandlers{full_source_revision,full_semantic_revision,full_policy_revision,..}=terminal.frame else{panic!("actual conditional siblings must not be relabeled as Model/Source/exclusive Handler")};assert_eq!(full_source_revision.is_some(),full);assert_eq!(full_semantic_revision.is_some(),full);assert_eq!(full_policy_revision.is_some(),full);
  let payload=&actual.stdout[end+1..];let diagnostic_len=usize::try_from(terminal.diagnostics.as_ref().map_or(0,|seal|seal.length)).unwrap();assert_eq!(diagnostic_len.checked_add(usize::try_from(terminal.report.length).unwrap()).unwrap(),payload.len());let(diagnostics,report)=payload.split_at(diagnostic_len);match terminal.diagnostics{Some(seal)=>assert_eq!(seal.hash.0,xxhash_rust::xxh3::xxh3_128(diagnostics)),None=>assert!(diagnostics.is_empty())}assert_eq!(terminal.report.hash.0,xxhash_rust::xxh3::xxh3_128(report));assert_eq!(String::from_utf8_lossy(diagnostics).contains("SOURCE_HANDLER_UNION_NOTICE"),full);let report=String::from_utf8_lossy(report);assert!(report.contains("code/raw_source.dm")&&report.contains("code/structural.dm"));assert!(!report.contains("allow annotations:"),"requested unused=true must not invent an audit in positive-only context");no_products(&root);
 }
}
